<template><section class="routines-page"><BioNexusFormErrors :errors="loadError" /><section class="bio-nexus-administrative-directory"><div v-if="loading" class="bio-nexus-empty-state">Cargando rutinas...</div><div v-else-if="!rows.length" class="bio-nexus-empty-state">No existen rutinas registradas.</div><BioNexusDataGrid v-else class="routines-grid" :row-data="rows" :column-defs="columnDefs" :default-col-def="defaultColDef" :components="gridComponents" :get-row-id="getRowId" :quick-filter-text="searchText" :search-enabled="true" v-model:search-model-value="searchText" search-placeholder="Buscar rutina" :refresh-enabled="true" :refreshing="loading" :refresh-disabled="saving" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="300" :max-grid-height="560" @refresh="loadRows" @row-context-menu="openContextMenu"><template #actions><BioNexusActionButton v-if="canCreate" icon="create" icon-only shape="rounded" size="md" variant="primary" label="Nueva rutina" :disabled="loading||saving" @click="formDialog?.openCreate()" /></template></BioNexusDataGrid><BioNexusContextMenu ref="contextMenu" :open="contextState.open" :x="contextState.x" :y="contextState.y" :items="contextItems" @close="closeContextMenu" @select="runContextAction"/></section><RoutineDialog ref="formDialog" :saving="saving" :can-create="canCreate" :can-update="canUpdate" :exams="exams" @submit="saveForm"/><BioNexusConfirmDialog ref="deleteDialog"/><BioNexusStateDialog ref="stateDialog" :saving="saving" @confirm="confirmStatus"/></section></template>
<script setup>
import{computed,nextTick,onMounted,ref}from"vue";import BioNexusDataGrid from"@/components/grid/BioNexusDataGrid.vue";import BioNexusGridActionsCell from"@/components/grid/BioNexusGridActionsCell.vue";import BioNexusGridToggleCell from"@/components/grid/BioNexusGridToggleCell.vue";import BioNexusOptionFilter from"@/components/grid/BioNexusOptionFilter.vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusConfirmDialog from"@/components/ui/BioNexusConfirmDialog.vue";import BioNexusStateDialog from"@/components/ui/BioNexusStateDialog.vue";import BioNexusFormErrors from"@/components/ui/BioNexusFormErrors.vue";import BioNexusContextMenu from"@/components/ui/BioNexusContextMenu.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import RoutineDialog from"@/components/routines/RoutineDialog.vue";import{getExamGroups,getExamsByGroup}from"@/services/examCatalogService";import{changeRoutineStatus,createRoutine,deleteRoutine,getRoutines,routineError,updateRoutine}from"@/services/routinesService";import{useAuthorizationStore}from"@/stores/authorization";import{useBioNexusToast}from"@/composables/useBioNexusToast";
const authorization=useAuthorizationStore(),toast=useBioNexusToast(),rows=ref([]),exams=ref([]),loading=ref(false),saving=ref(false),loadError=ref(""),searchText=ref(""),formDialog=ref(null),deleteDialog=ref(null),stateDialog=ref(null),deleteTarget=ref(null),contextMenu=ref(null),contextState=ref({open:false,x:0,y:0,row:null});const canCreate=computed(()=>authorization.hasPermission("routines.create")),canUpdate=computed(()=>authorization.hasPermission("routines.update")),canDelete=computed(()=>authorization.hasPermission("routines.delete"));const defaultColDef=Object.freeze({sortable:true,filter:true,resizable:true,suppressHeaderMenuButton:true}),gridComponents=Object.freeze({BioNexusGridActionsCell,BioNexusGridToggleCell});const columnDefs=computed(()=>[{field:"description",headerName:"Descripción",minWidth:260,flex:1,sort:"asc"},{field:"details",headerName:"Detalles",minWidth:280,flex:1.2},{field:"examCount",headerName:"Exámenes",width:130,cellClass:"routines-center",headerClass:"routines-center-header"},{field:"isActive",headerName:"Estado",width:175,cellClass:"routines-center",headerClass:"routines-center-header",filter:BioNexusOptionFilter,filterParams:{options:[{value:true,label:"Activo"},{value:false,label:"Desactivado"}]},cellRenderer:"BioNexusGridToggleCell",cellRendererParams:{onLabel:"Activo",offLabel:"Desactivado",ariaLabel:"Estado",disabled:()=>!canUpdate.value||saving.value,onToggle:requestStatus}},{colId:"actions",headerName:"Acciones",width:110,sortable:false,filter:false,resizable:false,headerClass:"bio-nexus-grid-actions-header",cellClass:"bio-nexus-grid-actions-cell",cellRenderer:"BioNexusGridActionsCell",cellRendererParams:{actions:[{key:"edit",label:"Editar",icon:"edit",visible:()=>canUpdate.value,disabled:()=>saving.value,onClick:row=>formDialog.value?.openEdit(row)},{key:"delete",label:"Eliminar",icon:"delete",variant:"danger",visible:()=>canDelete.value,disabled:()=>saving.value,onClick:openDelete}]}}]);const contextItems=computed(()=>{const row=contextState.value.row;return row?[{key:"edit",label:"Editar",icon:"edit",visible:canUpdate.value,action:()=>formDialog.value?.openEdit(row)},{key:"status",label:row.isActive?"Desactivar rutina":"Activar rutina",icon:row.isActive?"deactivate":"activate",variant:row.isActive?"danger":"default",visible:canUpdate.value,disabled:saving.value,action:()=>requestStatus(row)},{key:"delete",label:"Eliminar",icon:"delete",variant:"danger",visible:canDelete.value,disabled:saving.value,action:()=>openDelete(row)}]:[]});
function getRowId({data}){return String(data.id)}async function loadRows(){if(loading.value||saving.value)return;loading.value=true;loadError.value="";try{const[loaded,groups]=await Promise.all([getRoutines(),getExamGroups()]);rows.value=loaded;exams.value=(await Promise.all(groups.map(group=>getExamsByGroup(group.id)))).flat().sort((a,b)=>a.description.localeCompare(b.description))}catch(error){rows.value=[];loadError.value=routineError(error,"No fue posible consultar las rutinas.");toast.error(loadError.value)}finally{loading.value=false}}function compareRoutines(left,right){return left.description.localeCompare(right.description,"es",{sensitivity:"base"})||left.id-right.id}function replaceRow(saved){const currentIndex=rows.value.findIndex(row=>row.id===saved.id);if(currentIndex>=0)rows.value.splice(currentIndex,1);const insertIndex=rows.value.findIndex(row=>compareRoutines(saved,row)<0);rows.value.splice(insertIndex<0?rows.value.length:insertIndex,0,saved)}async function saveForm(payload){if(saving.value)return;saving.value=true;formDialog.value?.clearError();try{const saved=payload.mode==="create"?await createRoutine(payload.values):await updateRoutine(payload.record.id,payload.values);replaceRow(saved);formDialog.value?.close();toast.success(payload.mode==="create"?"Rutina creada correctamente.":"Rutina actualizada correctamente.")}catch(error){formDialog.value?.setError(routineError(error,"No fue posible guardar la rutina."))}finally{saving.value=false}}function requestStatus(row){if(!row||saving.value)return;closeContextMenu();stateDialog.value?.open(row,{kicker:"Estado de la rutina",label:item=>item.description,isInactive:item=>!item.isActive,activateTitle:"Activar rutina",deactivateTitle:"Desactivar rutina",activateMessage:"La rutina volverá a estar disponible para nuevos procesos.",deactivateMessage:"La rutina permanecerá visible, pero no estará disponible en nuevos procesos.",dangerOnDeactivate:true})}async function confirmStatus(row){if(!row||saving.value)return;saving.value=true;stateDialog.value?.clearError();try{const saved=await changeRoutineStatus(row.id,!row.isActive);replaceRow(saved);stateDialog.value?.close();toast.success(row.isActive?"Rutina desactivada.":"Rutina activada.")}catch(error){stateDialog.value?.setError(routineError(error,"No fue posible cambiar el estado de la rutina."))}finally{saving.value=false}}async function openDelete(row){const confirmed=await deleteDialog.value?.ask({kicker:"Confirmación",title:"Eliminar rutina",message:`Se eliminará ${row.description} y sus relaciones.`,icon:"delete",variant:"danger",confirmIcon:"delete",confirmText:"Sí, eliminar rutina",cancelText:"Cancelar"});if(!confirmed)return;deleteTarget.value=row;await confirmDelete()}async function confirmDelete(){if(!deleteTarget.value||saving.value)return;saving.value=true;try{await deleteRoutine(deleteTarget.value.id);rows.value=rows.value.filter(row=>row.id!==deleteTarget.value.id);deleteTarget.value=null;toast.success("Rutina eliminada correctamente.")}catch(error){toast.error(routineError(error,"No fue posible eliminar la rutina."))}finally{saving.value=false}}async function openContextMenu({event,row}){if(!canUpdate.value&&!canDelete.value)return;event.preventDefault();contextState.value={open:true,x:event.clientX,y:event.clientY,row};await nextTick();contextMenu.value?.positionMenu?.()}function closeContextMenu(){contextState.value={open:false,x:0,y:0,row:null}}async function runContextAction(item){const action=item?.action;closeContextMenu();if(typeof action==="function")await action()}onMounted(loadRows);
</script>
<style scoped>
.routines-page,.routines-grid{min-width:0}.routines-page :deep(.routines-grid .routines-center),.routines-page :deep(.routines-grid .routines-center-header .ag-header-cell-label){justify-content:center}.routines-page :deep(.routines-grid .ag-pinned-right-header),.routines-page :deep(.routines-grid .ag-pinned-right-cols-container){border-left:1px solid var(--bio-nexus-color-border-strong);box-shadow:calc(var(--bio-nexus-space-1)*-1) 0 var(--bio-nexus-space-3) var(--bio-nexus-shadow-panel-soft)}
</style>
